/**#@+
 * The different types of events that can create question states
 */
define('QUESTION_EVENTOPEN', '0');
// The state was created by Moodle
define('QUESTION_EVENTNAVIGATE', '1');
// The responses were saved because the student navigated to another page (this is not currently used)
define('QUESTION_EVENTSAVE', '2');
// The student has requested that the responses should be saved but not submitted or validated
define('QUESTION_EVENTGRADE', '3');
// Moodle has graded the responses. A SUBMIT event can be changed to a GRADE event by Moodle.
define('QUESTION_EVENTDUPLICATE', '4');
// The responses submitted were the same as previously
define('QUESTION_EVENTVALIDATE', '5');
// The student has requested a validation. This causes the responses to be saved as well, but not graded.
define('QUESTION_EVENTCLOSEANDGRADE', '6');
// Moodle has graded the responses. A CLOSE event can be changed to a CLOSEANDGRADE event by Moodle.
define('QUESTION_EVENTSUBMIT', '7');
// The student response has been submitted but it has not yet been marked
define('QUESTION_EVENTCLOSE', '8');
// The response has been submitted and the session has been closed, either because the student requested it or because Moodle did it (e.g. because of a timelimit). The responses have not been graded.
define('QUESTION_EVENTMANUALGRADE', '9');
// Grade was entered by teacher
define('QUESTION_EVENTS_GRADED', null);
